'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const layers=[
 {name:'Seawater intake',tag:'SOURCE & QUALITY',desc:'The first decision starts at the coast. Intake monitoring provides the quality context for every downstream production decision.',specs:[['Assets','INT-01 · Q-01'],['Modeled intake','1,250 m³/h'],['Watch condition','Algal-bloom warning']],type:'intake'},
 {name:'Reverse osmosis',tag:'DESALINATION & PRODUCTION',desc:'Two reverse-osmosis units convert pretreated seawater into fresh water. Production changes affect both energy demand and strategic reserves.',specs:[['Assets','RO-01 · RO-02'],['Combined production','600 m³/h'],['Demo energy intensity','3.5 kWh/m³']],type:'plant'},
 {name:'Strategic storage',tag:'BUFFER & RESILIENCE',desc:'Three reservoirs separate the rhythm of production from the rhythm of demand. Stored water creates flexibility, but the demo reserve floor limits how far production can be reduced.',specs:[['Assets','RES-01 · RES-02 · RES-03'],['Combined capacity','10,000 m³'],['Demo safety floor','35%']],type:'reservoir'},
 {name:'Pumping & transmission',tag:'MOVEMENT & CONTROL',desc:'Pumps sustain delivery through the transmission network. Valves are control boundaries: investigating an asset is different from authorizing a change.',specs:[['Assets','PMP-01 · V-04'],['Modeled delivery','550 m³/h'],['Control mode','Inspection only']],type:'pump'},
 {name:'Urban distribution',tag:'SERVICE & DEMAND',desc:'Five urban sectors draw water from the shared network. Comparing local pressure with excess inflow helps distinguish a physical loss from an unreliable reading.',specs:[['Assets','SEC-01 through SEC-05'],['Combined demand','550 m³/h'],['Disruption focus','Sector 4']],type:'city'}
];
let selectedLayer=1,expanded=true,flat=false;
function proj(x,y,z=0){return [x-y,(x+y)*.43-z]}
function polygon(points,fill,stroke='#507173',sw=.7){return `<polygon points="${points.map(p=>p.join(',')).join(' ')}" fill="${fill}" stroke="${stroke}" stroke-width="${sw}"/>`}
function box(x,y,w,d,h,color='#66817e') {let p=(a,b,c)=>proj(a,b,c);return polygon([p(x,y,h),p(x+w,y,h),p(x+w,y+d,h),p(x,y+d,h)],color)+polygon([p(x,y,0),p(x+w,y,0),p(x+w,y,h),p(x,y,h)],'#2f4e50')+polygon([p(x+w,y,0),p(x+w,y+d,0),p(x+w,y+d,h),p(x+w,y,h)],'#19373d');}
function cylinder(x,y,r,h){let [a,b]=proj(x,y);return `<path d="M${a-r} ${b-h}v${h}a${r} ${r*.43} 0 0 0 ${r*2} 0v-${h}" fill="#496a68" stroke="#86a19a" stroke-width=".7"/><ellipse cx="${a}" cy="${b-h}" rx="${r}" ry="${r*.43}" fill="#9bada2" stroke="#c6bba1" stroke-width=".7"/><ellipse cx="${a}" cy="${b-h}" rx="${r*.7}" ry="${r*.3}" fill="none" stroke="#637e78" stroke-width=".7"/>`}
function line3(points,col='#82c6ba',width=2){return `<polyline points="${points.map(p=>proj(...p).join(',')).join(' ')}" stroke="${col}" stroke-width="${width}" fill="none"/>`}
function equipment(i){let s='';if(i===0){for(let n=0;n<8;n++)s+=line3([[5,n*20,2],[165,n*20,2]],'#467b80',1);s+=box(35,42,55,60,13,'#77918a');s+=line3([[65,70,20],[65,125,20],[150,125,20]],'#c6ad80',5);s+=cylinder(140,125,8,22);for(let n=0;n<4;n++)s+=box(110,n*18+30,30,9,5,'#8bb2a8');}
if(i===1){s+=box(15,25,145,110,6,'#6d8580');for(let row=0;row<2;row++)for(let n=0;n<6;n++){let [x,y]=proj(35+n*18,45+row*50,19);s+=`<path d="M${x} ${y}l-21 9" stroke="#b4b9a7" stroke-width="7"/><ellipse cx="${x}" cy="${y}" rx="4" ry="3" fill="#e4d5b9"/>`;}s+=box(130,95,22,30,26,'#9aab9e');s+=line3([[20,25,10],[150,25,10],[150,125,10]],'#c6ad80',2);}
if(i===2){s+=cylinder(52,45,29,34)+cylinder(120,50,29,34)+cylinder(90,115,32,37);s+=line3([[52,45,2],[52,142,2],[140,142,2],[140,50,2]],'#90bdb0',3)}
if(i===3){s+=box(20,25,130,115,7,'#617e78');for(let n=0;n<3;n++){s+=box(40+n*35,58,20,36,16,'#98a99c');s+=cylinder(50+n*35,62,8,23);}s+=line3([[15,35,13],[140,35,13],[140,120,13],[25,120,13]],'#c6ad80',4);s+=box(25,100,20,20,24,'#9caa9d');}
if(i===4){for(let a=0;a<4;a++)for(let b=0;b<3;b++){let h=12+((a*3+b*7)%5)*9;s+=box(20+a*35,20+b*44,22,25,h,'#87998f')}for(let a=0;a<3;a++)s+=line3([[12,53+a*44,1],[160,53+a*44,1]],'#7a9c90',1)}return s;}
function renderExploded(){if(flat){$('#exploded').innerHTML=`<div class="diagram-list">${layers.map((l,i)=>`<button data-layer="${i}" class="${selectedLayer===i?'active':''}">${l.name}<small>${l.tag} · ${l.specs[0][1]}</small></button>`).join('')}</div>`;return;}
let s=`<svg viewBox="0 0 620 560" role="group" aria-label="Exploded five-layer desalination infrastructure model"><defs><pattern id="isogrid" width="48" height="24" patternUnits="userSpaceOnUse"><path d="M0 12 24 0 48 12 24 24Z" fill="none" stroke="#244047" stroke-width=".5"/></pattern></defs><ellipse cx="280" cy="498" rx="210" ry="55" fill="#102a2e" opacity=".6"/><path d="M40 500 290 360 560 490 310 640Z" fill="url(#isogrid)" opacity=".45"/><g stroke="#c6ad80" stroke-width=".7" stroke-dasharray="3 6" opacity=".4"><path d="M150 80V440M320 80V440M405 140V510"/></g>`;
for(let i=4;i>=0;i--){let y=expanded?50+i*91:215+i*22;s+=`<g class="layer-group ${selectedLayer===i?'selected':''}" data-layer="${i}" role="button" tabindex="0" aria-label="Explore ${layers[i].name}" transform="translate(270 ${y})"><path d="M-170 72 0 145 170 72V81L0 155 -170 81Z" fill="#102b30" stroke="#426364" stroke-width=".7"/><path class="slab-top" d="M0 0 170 72 0 145 -170 72Z" fill="#173439" stroke="#527879" stroke-width=".7"/>${equipment(i)}<path d="M170 72h35" stroke="#637b77" stroke-width=".7"/><text x="214" y="69" class="layer-label">${['INTAKE','DESALINATION','STORAGE','TRANSMISSION','DISTRIBUTION'][i]}</text><text x="214" y="84" fill="#587577" font-family="monospace" font-size="9">${['QUALITY MONITORING','REVERSE OSMOSIS','STRATEGIC RESERVES','PUMPS & VALVES','FIVE URBAN SECTORS'][i]}</text></g>`;}$('#exploded').innerHTML=s+'</svg>';}
function selectLayer(i,scroll=false){selectedLayer=i;renderExploded();$('#layerList').innerHTML=layers.map((l,j)=>`<button data-layer="${j}" class="${i===j?'active':''}">${l.name}<span>${i===j?'−':'＋'}</span></button>`).join('');const l=layers[i];$('#layerInspector').innerHTML=`<span class="eyebrow">${l.tag}</span><svg viewBox="-190 -50 380 230" aria-hidden="true">${equipment(i)}</svg><h3>${l.name}</h3><p>${l.desc}</p>${l.specs.map(s=>`<div class="spec"><span>${s[0]}</span><b>${s[1]}</b></div>`).join('')}<button class="textbutton" data-inspect-layer="${i}">Inspect in the network</button>`;if(scroll)$('#infrastructure').scrollIntoView({behavior:'smooth'});}
$('#explodeToggle').onclick=()=>{expanded=!expanded;$('#explodeToggle').textContent=expanded?'Collapse layers':'Expand layers';renderExploded()};$('#diagramToggle').onclick=()=>{flat=!flat;$('#diagramToggle').textContent=flat?'Spatial view':'2D view';$('#explodeToggle').disabled=flat;renderExploded()};$('#explore').onclick=()=>$('#infrastructure').scrollIntoView({behavior:'smooth'});
const assets=[
{id:'INT-01',name:'Coastal intake',type:'intake',x:110,y:300}, {id:'RO-01',name:'Desalination unit 1',type:'plant',x:280,y:220}, {id:'RO-02',name:'Desalination unit 2',type:'plant',x:280,y:400}, {id:'RES-01',name:'North reservoir',type:'reservoir',x:450,y:140}, {id:'RES-02',name:'Central reservoir',type:'reservoir',x:450,y:310},{id:'RES-03',name:'South reservoir',type:'reservoir',x:450,y:480}, {id:'PMP-01',name:'Transmission pump',type:'pump',x:610,y:310}, {id:'V-04',name:'Sector 4 valve',type:'valve',x:730,y:430}, {id:'SEC-01',name:'Sector 1 · North',type:'sector',x:800,y:100},{id:'SEC-02',name:'Sector 2 · East',type:'sector',x:800,y:210},{id:'SEC-03',name:'Sector 3 · Central',type:'sector',x:800,y:320},{id:'SEC-04',name:'Sector 4 · Harbour',type:'sector',x:850,y:475},{id:'SEC-05',name:'Sector 5 · South',type:'sector',x:720,y:570}];
const edges=[['INT-01','RO-01',625],['INT-01','RO-02',625],['RO-01','RES-01',200],['RO-01','RES-02',100],['RO-02','RES-02',100],['RO-02','RES-03',200],['RES-01','PMP-01',180],['RES-02','PMP-01',190],['RES-03','PMP-01',180],['PMP-01','SEC-01',100],['PMP-01','SEC-02',120],['PMP-01','SEC-03',130],['PMP-01','V-04',110],['V-04','SEC-04',110],['PMP-01','SEC-05',90]];
let disrupted=false,selected='RES-02',tab='twin',plan='baseline',zoom=1,pan={x:0,y:0},quarantined=false;let audit=[{time:'13:00',title:'Demo network initialized',text:'Baseline synthetic topology loaded. No external telemetry or control connection.'}];
const asset=id=>assets.find(a=>a.id===id);let critical=a=>disrupted&&['SEC-04','V-04'].includes(a.id);let warn=a=>disrupted&&a.id==='INT-01';
function glyph(type,x=0,y=0){let s={intake:'<path d="M-13 4q6-8 12 0t12 0M-13 11q6-8 12 0t12 0M0-14v13m-5-4 5 5 5-5"/>',plant:'<rect x="-13" y="-9" width="26" height="18"/><path d="M-9-5h18M-9 0h18M-9 5h18"/>',reservoir:'<ellipse cy="-9" rx="13" ry="5"/><path d="M-13-9v18c0 7 26 7 26 0V-9M-13 3c0 6 26 6 26 0"/>',pump:'<circle r="12"/><path d="m-5-7 12 7-12 7ZM-18 0h6m24 0h6"/>',valve:'<path d="m-13-9 26 18V-9L-13 9ZM0 0v-15m-7 0h14"/>',sector:'<path d="M-13 12V-3h8v15m0 0V-13h10v25m0 0V-5h8v17M-2-8h4m-4 6h4m-4 6h4"/>'}[type];return `<g transform="translate(${x} ${y})" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round">${s}</g>`;}
function metrics(){let loss=disrupted?65:0;$('#metrics').innerHTML=[['Production','600','m³/h'],['Urban demand','550','m³/h'],['Stored reserve','62','%'],['Modeled loss',loss,'m³/h'],['Active alerts',disrupted?3:0,'']].map(([l,v,u])=>`<div class="metric"><span>${l}</span><strong class="${l==='Active alerts'&&disrupted?'coral':''}">${v}</strong><small>${u}</small></div>`).join('');$('#simTime').textContent=disrupted?'14:00 GST':'13:00 GST';$('#networkStatus').textContent=disrupted?'COMPOUND DISRUPTION':'NORMAL OPERATIONS';$('#networkStatus').style.color=disrupted?'var(--warning)':'';$('#disrupt').disabled=disrupted;}
function renderNetwork(){const query=$('#search').value.toLowerCase(),trace=$('#traceToggle').checked;let connected=new Set([selected]);if(trace){let queue=[selected];while(queue.length){let id=queue.shift();edges.filter(e=>e[1]===id&&e[2]>0).forEach(e=>{if(!connected.has(e[0])){connected.add(e[0]);queue.push(e[0])}})}}let s=`<defs><pattern id="grid" width="30" height="30" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".8" fill="#335055"/></pattern></defs><rect width="950" height="650" fill="url(#grid)"/><g id="mapContent" transform="translate(${pan.x} ${pan.y}) scale(${zoom})"><path d="M0 0h135q-40 90-20 170t-15 150 15 160-20 170H0Z" fill="#14323c" opacity=".65"/><path d="M135 0q-40 90-20 170t-15 150 15 160-20 170" stroke="#35616b" fill="none" stroke-dasharray="3 5"/><text x="25" y="50" fill="#59848b" font-size="11" font-family="monospace" letter-spacing="3">COAST</text>`;
for(const [a,b,f]of edges){let p=asset(a),q=asset(b),isBad=server.loss>0&&['V-04','SEC-04'].includes(b);let modeledFlow=f;let path=`M${p.x} ${p.y}H${(p.x+q.x)/2}V${q.y}H${q.x}`;let dim=trace&&!(connected.has(a)&&connected.has(b));s+=`<g opacity="${dim?.12:1}"><path class="pipe" d="${path}" style="${isBad?'stroke:var(--danger)':''}"/>${$('#flowToggle').checked&&modeledFlow>0?`<path class="flow ${isBad?'critical':''}" d="${path}" style="animation-duration:${(1200/modeledFlow).toFixed(1)}s"/>`:''}</g>`;}
for(const a of assets){let dim=(query&&!`${a.id} ${a.name} ${a.type}`.toLowerCase().includes(query))||(trace&&!connected.has(a.id));let color=critical(a)?'var(--danger)':warn(a)?'var(--warning)':'var(--teal)';s+=`<g class="node ${a.id===selected?'selected':''}" data-asset="${a.id}" role="button" tabindex="0" aria-label="${a.id}, ${a.name}${critical(a)?', incident':''}" transform="translate(${a.x} ${a.y})" opacity="${dim?.16:1}" style="color:${color}"><circle class="ring" r="27" style="${critical(a)||warn(a)?'stroke:'+color:''}"/>${glyph(a.type)}${$('#labelToggle').checked?`<text y="47" text-anchor="middle">${a.id}</text><text class="sub" y="62" text-anchor="middle">${a.type==='sector'?a.name.split(' · ')[1]:a.type==='reservoir'?'62% storage':a.type==='plant'?'300 m³/h':a.type==='intake'?'1,250 m³/h':a.type==='pump'?`${disrupted?615:550} m³/h`:'OPEN'}${critical(a)?' · !':''}</text>`:''}</g>`;}$('#network').innerHTML=s+'</g>';}
function inspect(id){selected=id;renderNetwork();let a=asset(id),status=critical(a)?'! LEAK INVESTIGATION':warn(a)?'! QUALITY REVIEW':'✓ NORMAL';let facts=a.type==='reservoir'?[['Storage','62%'],['Capacity',a.id==='RES-02'?'4,000 m³':'3,000 m³'],['Demo floor','35%']]:a.type==='plant'?[['Production','300 m³/h'],['Energy intensity','3.5 kWh/m³'],['Feedwater','625 m³/h']]:a.type==='intake'?[['Intake flow','1,250 m³/h'],['Q-01 status',disrupted?(quarantined?'Quarantined':'Flatline detected'):'Variable signal'],['Quality alert',disrupted?'Bloom warning':'None in scenario']]:a.type==='sector'?[['Demand',edges.find(e=>e[1]===id)[2]+' m³/h'],['Pressure',id==='SEC-04'&&disrupted?'1.7 bar':'3.8 bar'],['Excess inflow',id==='SEC-04'&&disrupted?'65 m³/h':'0 m³/h']]:a.type==='valve'?[['State','Open'],['Flow',(disrupted?175:110)+' m³/h'],['Control','Inspection only']]:[['Delivery',(disrupted?615:550)+' m³/h'],['Head (illustrative)','42 m'],['State','Running']];let links=edges.filter(e=>e[0]===id||e[1]===id).map(e=>e[0]===id?e[1]:e[0]);$('#assetInspector').innerHTML=`<span class="asset-type">${a.type.toUpperCase()} / ${a.id}</span><div class="asset-icon" style="color:var(--gold)"><svg viewBox="-50 -35 100 70">${glyph(a.type)}</svg></div><h3>${a.name}</h3><span class="asset-status ${critical(a)?'coral':warn(a)?'amber':''}">${status}</span>${facts.map(([k,v])=>`<div class="spec"><span>${k}</span><b>${v}</b></div>`).join('')}<h4>Connected assets</h4><p>${links.map(l=>`<button class="asset-link" data-asset="${l}" style="color:var(--teal);padding:5px 5px 5px 0">${l}</button>`).join(' · ')}</p><h4>${critical(a)?'Independent leak evidence':'Operational context'}</h4><p>${critical(a)?'Sector 4 pressure falls from 3.8 to 1.7 bar while inflow rises from 110 to 175 m³/h. The independent signals support the injected leak.':warn(a)?'A flatlined quality sensor cannot establish safe water quality. Review its history and the separate coastal warning.':a.type==='reservoir'?'Storage buffers the difference between production and downstream delivery. Compare plans before proposing a production change.':'Select upstream or downstream assets to follow the water path through this synthetic network.'}</p><button class="outline" id="traceAsset">${$('#traceToggle').checked?'Clear upstream trace':'Trace upstream connections'}</button>${a.type==='reservoir'||a.type==='plant'?'<button class="primary" data-tab="energy">Compare production plans</button>':warn(a)?'<button class="primary" data-tab="diagnostics">Review sensor evidence</button>':critical(a)?'<button class="primary" data-tab="incidents">Inspect incident</button>':''}`;$('#traceAsset').onclick=()=>{$('#traceToggle').checked=!$('#traceToggle').checked;inspect(selected)};}
function addAudit(title,text){audit.unshift({time:disrupted?'14:00':'13:00',title,text});}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function enter(id){location.hash='control';if(id)selected=id;showRoute()}
function showRoute(){let app=location.hash==='#control';$('#landing').hidden=app;$('#application').hidden=!app;if(app){metrics();setTab(tab);window.scrollTo(0,0)}}
function setTab(t){tab=t;$$('.sidebar [data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));$('#twinPanel').hidden=t!=='twin';$('#detailPanel').hidden=t==='twin';if(t==='twin')inspect(selected);else renderDetail();}
function renderDetail(){}
function chart(series,floor=null,unit='%',labels=['14:00','16:00','18:00','20:00','22:00']){let max=unit==='%'?100:Math.max(...series.flatMap(s=>s.values))*1.2,min=0;let x=i=>45+i*490/(series[0].values.length-1),y=v=>210-v/max*170;return `<svg class="chart" viewBox="0 0 570 255" role="img" aria-label="${series.map(s=>s.name).join(', ')} chart in ${unit}">${[0,.25,.5,.75,1].map(v=>`<path d="M45 ${y(max*v)}H535" stroke="#294044"/><text x="5" y="${y(max*v)+4}">${Math.round(max*v)}</text>`).join('')}${floor!==null?`<path d="M45 ${y(floor)}H535" stroke="#dd766b" stroke-dasharray="5 5"/><text x="320" y="${y(floor)-7}" style="fill:#dd766b">${floor}% RESERVE FLOOR</text>`:''}${series.map(s=>`<polyline points="${s.values.map((v,i)=>`${x(i)},${y(v)}`).join(' ')}" fill="none" stroke="${s.color}" stroke-width="2.5"/>`).join('')}${labels.map((l,i)=>`<text x="${45+i*490/(labels.length-1)}" y="239" text-anchor="middle">${l}</text>`).join('')}</svg>`;}
$('#search').oninput=()=>{renderNetwork();let q=$('#search').value.trim().toLowerCase();if(q){let match=assets.filter(a=>`${a.id} ${a.name}`.toLowerCase().includes(q));if(match.length===1)inspect(match[0].id)}};['flowToggle','labelToggle','traceToggle'].forEach(id=>$('#'+id).onchange=()=>inspect(selected));$('#zoomIn').onclick=()=>{zoom=Math.min(zoom*1.2,2.5);renderNetwork()};$('#zoomOut').onclick=()=>{zoom=Math.max(zoom/1.2,.6);renderNetwork()};$('#fit').onclick=()=>{zoom=1;pan={x:0,y:0};renderNetwork()};let drag=null,moved=false;
$('#network').onpointerdown=e=>{if(e.target.closest('.node'))return;drag={x:e.clientX,y:e.clientY,px:pan.x,py:pan.y};moved=false;$('#network').setPointerCapture(e.pointerId)};$('#network').onpointermove=e=>{if(!drag)return;let scale=950/$('#network').getBoundingClientRect().width;pan={x:drag.px+(e.clientX-drag.x)*scale,y:drag.py+(e.clientY-drag.y)*scale};moved=true;renderNetwork()};$('#network').onpointerup=()=>drag=null;$('#network').onpointercancel=()=>drag=null;
document.addEventListener('click',e=>{let b=e.target.closest('[data-layer],[data-enter],[data-inspect-layer],[data-asset],[data-tab],[data-plan],[data-focus]');if(!b)return;if(b.dataset.layer!==undefined)selectLayer(+b.dataset.layer,true);if(b.hasAttribute('data-enter'))enter();if(b.dataset.inspectLayer!==undefined)enter(['INT-01','RO-01','RES-02','PMP-01','SEC-04'][+b.dataset.inspectLayer]);if(b.dataset.asset)inspect(b.dataset.asset);if(b.dataset.tab)setTab(b.dataset.tab);if(b.dataset.plan){plan=b.dataset.plan;renderDetail()}if(b.dataset.focus){selected=b.dataset.focus;setTab('twin')}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('g[role="button"]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});window.addEventListener('hashchange',showRoute);selectLayer(1);
